cd ~/aloha_data/insertion_qual; python3 -c "
import csv
for e in range(5):
  rows=[r for r in csv.reader(open(f'episode_{e}.csv')) if not r[0].startswith('#') and r[0]!='t']
  print('ep',e,len(rows))
  if e==2:
    for r in rows[::25]: print(' '.join(r))
  else:
    lg=[float(r[7]) for r in rows]; print(' left grip min/max/last', min(lg),max(lg),lg[-1])
"

